//@version=5
indicator("Dual Moving Averages", shorttitle="DMA", overlay=true)

// User-defined moving average periods with defaults
fastLength = input.int(10, title="Fast MA Period", minval=1)
slowLength = input.int(100, title="Slow MA Period", minval=1)

// Calculating moving averages
fastMA = ta.sma(close, fastLength)
slowMA = ta.sma(close, slowLength)

// Plotting moving averages
plot(fastMA, title="Fast MA", color=color.blue)
plot(slowMA, title="Slow MA", color=color.red)

// Generating buy and sell signals
buySignal = ta.crossover(fastMA, slowMA)
sellSignal = ta.crossunder(fastMA, slowMA)

// Plotting buy and sell labels
plotshape(series=buySignal, title="Buy Signal", location=location.belowbar,
          color=color.green, style=shape.labelup, text="BUY")
plotshape(series=sellSignal, title="Sell Signal", location=location.abovebar,
          color=color.red, style=shape.labeldown, text="SELL")
